import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry, 
  Group, 
  Mesh, 
  Vector2,
  Color,
  Texture
} from 'three/webgpu';
import { 
  uv, 
  vec3, 
  mix, 
  smoothstep, 
  uniform, 
  texture, 
  positionLocal, 
  varying,
  vec4,
  mul,
  add
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors || config.colors || {
    background: "#0b0b10",
    surface: "#16161d",
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    gradientStops: [{ at: 0.45, hex: "#0b0b1000" }, { at: 1, hex: "#0b0b10eb" }]
  };

  const primitivesList = [];

  // --- STAGE BACKDROP (STOPS FLAT VOID DEFECT) ---
  const bgGeom = new PlaneGeometry(8, 6.5);
  const bgMat = new MeshBasicNodeMaterial({ transparent: true });

  // Custom gradient for backdrop
  const gradUv = uv();
  const bgGradFactor = smoothstep(0.0, 1.0, gradUv.y);
  const bgColA = new Color('#050508');
  const bgColB = new Color(colors.background);
  bgMat.colorNode = mix(bgColB, bgColA, bgGradFactor);

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.z = -1.5;
  group.add(bgMesh);

  // --- PARALLAX PHOTO PLATE ---
  const widthVal = 4.0;
  const heightVal = 2.5;
  const geom = new PlaneGeometry(widthVal, heightVal, 96, 96);
  const plateMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.0 });

  // Uniform hooks for interaction/parallax
  const uParallaxOffset = uniform(0.0);
  const uDepthAmp = uniform(0.18);

  // Load textures
  let imageTex = null;
  let depthTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((t) => {
      imageTex = t;
      t.colorSpace = THREE.SRGBColorSpace;
      if (depthTex) applyShaders();
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((d) => {
      depthTex = d;
      if (imageTex) applyShaders();
    });
  }

  function applyShaders() {
    if (!imageTex || !depthTex) return;

    // Use WebGPU TSL nodes
    const texNode = texture(imageTex);
    const depthMapNode = texture(depthTex);

    // Apply vertex-level depth relocation based on depth map
    const depthValNode = depthMapNode.r;

    // Displace vertices in Z direction based on depth map & parallax
    const finalZ = mul(depthValNode, uDepthAmp);
    plateMat.positionNode = positionLocal.add(vec3(0, 0, finalZ));

    // Custom fragment shading (Filmic grading: lift blacks, soft shoulder, preserve accent reds)
    const baseColor = texNode.rgb;

    // Lift blacks to #0d0d12
    const liftedBlack = vec3(13/255, 13/255, 18/255);
    const graded = mix(liftedBlack, vec3(1.0), baseColor);

    // Contrast boost (midtones)
    const midContrast = mul(graded.sub(0.48), 1.12).add(0.48);

    // Global desaturation with red channel preserved (so #ff2a38 signal stays warm)
    const luma = midContrast.dot(vec3(0.299, 0.587, 0.114));
    const desat = mix(midContrast, vec3(luma), 0.08);

    // Simple protection for vibrant reds
    const redDiff = smoothstep(0.1, 0.5, desat.r.sub(desat.g));
    const finalColor = mix(desat, midContrast, redDiff);

    // Bottom gradient scrim integration
    const localUv = uv();
    const scrimFactor = smoothstep(0.45, 1.0, localUv.y.oneMinus()); // Bottom-heavy
    const scrimCol = new Color(colors.background);

    plateMat.colorNode = mix(finalColor, scrimCol, scrimFactor.mul(0.92));
    plateMat.needsUpdate = true;
  }

  const plateMesh = new Mesh(geom, plateMat);
  plateMesh.position.set(0, 0, 0);
  group.add(plateMesh);

  // --- CAPTION BLOCK & TEXT ---
  const textGroup = new Group();
  // Adjust position to left align with visual offset within the frame padding
  textGroup.position.set(-widthVal / 2 + 0.35, -heightVal / 2 + 0.35, 0.15);
  group.add(textGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Match verbatim content based on specifications
  const kickerStr = items.find(i => i.role === 'kicker')?.text || "NOVA ATELIER / GENEVA";
  const headlineStr = items.find(i => i.role === 'headline')?.text || "Time, Machined.";
  const bodyStr = items.find(i => i.role === 'body')?.text || "Every case begins as a single billet of 904L steel.";
  const captionStr = items.find(i => i.role === 'caption')?.text || "CALIBRE NA-01 / 72 HOUR RESERVE";

  // Draw items
  const kickerMesh = ctx.fontAtlas.createText(kickerStr, {
    fontSize: 0.08,
    color: colors.paper,
    align: 'left',
    letterSpacingPx: 1.2
  });
  textGroup.add(kickerMesh);

  const headlineMesh = ctx.fontAtlas.createText(headlineStr, {
    fontSize: 0.28,
    color: colors.paper,
    align: 'left'
  });
  headlineMesh.position.y = -0.28;
  textGroup.add(headlineMesh);

  // Accent hairline (emissive signal red red between headline and body)
  const hairGeom = new PlaneGeometry(0.75, 0.015);
  const hairMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent)
  });
  const hairMesh = new Mesh(hairGeom, hairMat);
  hairMesh.position.set(0.375, -0.48, 0.01);
  textGroup.add(hairMesh);

  const bodyMesh = ctx.fontAtlas.createText(bodyStr, {
    fontSize: 0.12,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 800
  });
  bodyMesh.position.y = -0.65;
  textGroup.add(bodyMesh);

  const captionMesh = ctx.fontAtlas.createText(captionStr, {
    fontSize: 0.08,
    color: colors.accent,
    align: 'left'
  });
  captionMesh.position.y = -0.92;
  textGroup.add(captionMesh);

  // --- ANIMATIONS & ENTRANCES ---
  const introTimeline = gsap.timeline();

  // Plate fade-in
  introTimeline.to(plateMat, {
    opacity: 1.0,
    duration: 0.5,
    ease: "cubic-bezier(0.25,0.46,0.45,0.94)"
  }, 0);

  // Caption block rise-in (starts 120ms after)
  textGroup.position.y -= 0.4;
  textGroup.visible = false;

  introTimeline.to(textGroup.position, {
    y: "+=0.4",
    duration: 0.7,
    ease: "power3.out",
    onStart: () => { textGroup.visible = true; }
  }, 0.12);

  // Apply cinematic primitives (specifically parallax-scroll dynamic binding)
  const cinematicPrimitives = config.cinematicPrimitives || [];
  cinematicPrimitives.forEach((primitive) => {
    if (ctx.primitives[primitive.name]) {
      const activePrim = ctx.primitives[primitive.name](group, primitive.params);
      primitivesList.push(activePrim);
    }
  });

  // Track page scroll to alter shader displacement properties organically
  const handleScroll = () => {
    const scrollY = window.scrollY || 0;
    const scrollLim = Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
    const scrollRatio = scrollY / scrollLim;

    // Map depth values contextually
    uParallaxOffset.value = scrollRatio * 0.14;
    uDepthAmp.value = 0.18 + scrollRatio * 0.04;
  };

  window.addEventListener('scroll', handleScroll, { passive: true });

  // Cleanup mechanics
  group.userData.cleanup = () => {
    introTimeline.kill();
    window.removeEventListener('scroll', handleScroll);
    primitivesList.forEach(prim => {
      if (prim && typeof prim.cleanup === 'function') {
        prim.cleanup();
      }
    });
    geom.dispose();
    plateMat.dispose();
    bgGeom.dispose();
    bgMat.dispose();
    hairGeom.dispose();
    hairMat.dispose();
  };

  return group;
}
